INSERT INTO products (category_id, name, slug, description, price, discount, stock, active, featured, main_image_url) VALUES
('c1111111-1111-1111-1111-111111111111', 'Acetaminofen Codeina Tableta x30 30mg', 'acetaminofen-codeina-tableta-x30-30mg-75801', 'Acetaminofén + Codeína 30 mg Tableta x 30 Una alternativa analgésica de apoyo para manejo del dolor moderado bajo indicación médica El Acetaminofén + Codeína 30 mg en tabletas x 30 unidades es un medicamento utilizado como apoyo en el manejo del dolor moderado, siempre bajo supervisión y prescripción médica. Es el insumo indicado para farmacias, instituciones de salud y operadores farmacéuticos que requieren presentaciones prácticas y de fácil dispensación. Su formato en tabletas permite una administración controlada y organizada dentro de entornos clínicos o de distribución autorizada.', 36023.00, 20, 18, true, true, 'https://www.abastece.co/abastece/images/75801.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Acetaminofen Tabletas Caja x100 500mg', 'acetaminofen-tabletas-caja-x100-500mg-5351', 'Acetaminofen 500 mg - Caja con 100 Tabletas Alivio Eficaz para el Dolor y la Fiebre Manten tu bienestar con el Acetaminofen de 500 mg, presentado en una caja con 100 tabletas. Este medicamento es ideal para el alivio temporal del dolor leve a moderado, como dolores de cabeza, musculares y fiebre. Su formula efectiva y de accion rapida te ayuda a sentirte mejor cuando mas lo necesitas. Siempre consulta a un profesional de la salud antes de usarlo. ¡Cuida de ti y de los tuyos con el acetaminofen de confianza!', 6730.00, 20, 26, true, true, 'https://www.abastece.co/abastece/images/5351.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Agua Oxigenada Frasco 120ml', 'agua-oxigenada-frasco-120ml-1921', 'Agua Oxigenada 120 ml: Versatilidad y Eficacia en un Frasco Práctico Tu Aliado para la Limpieza y el Cuidado Personal El Agua Oxigenada de 120 ml es un producto multifuncional que no puede faltar en tu hogar. Ideal para desinfectar heridas, blanquear ropa y limpiar superficies, su fórmula efectiva te ofrece una solución segura y accesible para diversas aplicaciones. Su práctico frasco te permite tenerla siempre a mano, asegurando que estés preparado para cualquier necesidad de limpieza o cuidado personal. ¡Descubre todos los beneficios que el agua oxigenada puede ofrecerte!', 3526.00, 20, 41, true, false, 'https://www.abastece.co/abastece/images/1921.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Alcohol Antiseptico 70 % Frasco Por 700 Ml Karest', 'alcohol-antiseptico-70-frasco-por-700-ml-karest-76481', 'Alcohol Antiséptico 70% Frasco x 700 ml Karest Una solución práctica para desinfección diaria en entornos de trabajo y cuidado El Alcohol Antiséptico 70% Karest x 700 ml es un insumo de uso frecuente para la limpieza y desinfección de superficies y apoyo en protocolos de higiene. Es el producto ideal para oficinas, instituciones de salud, áreas administrativas, industrias y kits de bioseguridad. Su concentración al 70% permite una acción efectiva, mientras su presentación en frasco facilita el uso continuo y controlado en distintos puntos de trabajo.', 5645.00, 20, 33, true, false, 'https://www.abastece.co/abastece/images/76481.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Alcohol Antiseptico al 70 % Botella 1000 ml', 'alcohol-antiseptico-al-70-botella-1000-ml-70283', 'Alcohol Antiseptico al 70% Botella 1000 ml Desinfección efectiva para tu salud y bienestar El Alcohol Antiseptico al 70% en presentación de 1000 ml es perfecto para la limpieza y desinfección de manos, superficies y heridas menores. Con su concentración de alcohol al 70%, proporciona una acción antibacteriana eficaz, ayudando a prevenir infecciones y manteniendo un ambiente más limpio. Su tamaño de 1000 ml es ideal para uso doméstico, en consultorios médicos o en espacios de trabajo, garantizando una desinfección rápida y conveniente en todo momento.', 7249.00, 20, 40, true, false, 'https://www.abastece.co/abastece/images/70283.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Alcohol Antiseptico JGB Al 70% Con Tapa 120ml', 'alcohol-antiseptico-jgb-al-70-con-tapa-120ml-73192', 'Alcohol Antiseptico al 70% JGB con Tapa 120 ml Proteccion y limpieza eficaz para tus manos y superficies El Alcohol Antiseptico al 70% JGB es ideal para desinfectar y proteger tus manos y superficies de bacterias y germenes. Su formula con un 70% de alcohol garantiza una accion rÃƒ¡pida y efectiva para eliminar microorganismos, ayudando a mantener un ambiente limpio y seguro. La presentacion de 120 ml con tapa facilita su uso y transporte, convirtiendolo en un accesorio indispensable para el hogar, la oficina o el bolso. Manten la higiene de manera prÃƒ¡ctica y eficiente con este alcohol antiseptico de alta calidad.', 3062.00, 20, 54, true, false, 'https://www.abastece.co/abastece/images/73192.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Alcohol Etilico Al 96% Galon 3800 Ml', 'alcohol-etilico-al-96-galon-3800-ml-75288', 'Alcohol Etílico al 96% Galón (3800 ml): Desinfección Profesional de Alto Nivel Alcohol Antiséptico Industrial para Protocolos de Bioseguridad y Limpieza Garantiza la máxima higiene en tus instalaciones con nuestro Alcohol Etílico al 96% en presentación de 3800 ml. Este antiséptico de alta concentración es la solución definitiva para empresas que exigen una desinfección profunda de superficies, equipos y áreas comunes. Su potente fórmula actúa de manera inmediata contra virus, bacterias y hongos, convirtiéndose en el insumo esencial para protocolos de bioseguridad en oficinas, consultorios e industrias. El formato en galón no solo optimiza el costo por litro, sino que facilita el reabastecimiento de dispensadores, asegurando un entorno laboral seguro y cumpliendo con los más altos estándares de sanidad institucional.', 32693.00, 20, 30, true, false, 'https://www.abastece.co/abastece/images/75288.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Alcohol Etilico Industrial Al 96% Galon X 20 Litros', 'alcohol-etilico-industrial-al-96-galon-x-20-litros-76167', 'h1&gt;Alcohol Etílico Industrial al 96% (Garrafa x 20 Litros) Solvente de alta pureza y desinfectante potente para procesos industriales El alcohol etílico industrial al 96% en presentación de 20 litros es un insumo técnico de alta concentración, diseñado para aplicaciones que requieren un solvente eficaz y de rápida evaporación. Su pureza lo hace ideal para la limpieza de componentes electrónicos, desinfección de superficies inertes y como materia prima en procesos químicos. Como producto institucional especializado, esta garrafa de gran formato asegura un suministro eficiente y económico para plantas de producción, talleres y empresas de mantenimiento que exigen los más altos estándares de higiene y solvencia técnica.', 108686.00, 20, 26, true, false, 'https://www.abastece.co/abastece/images/76167.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Alcohol Isopropilico Al 70 % De 700 Ml', 'alcohol-isopropilico-al-70-de-700-ml-76078', 'Alcohol Isopropílico al 70% de 700 ml x Unidad Solución de limpieza técnica que optimiza la bioseguridad operativa Alcohol isopropílico al 70% en presentación de 700 ml, formulado para limpieza y desinfección de superficies y componentes sin dejar residuos. Su concentración balanceada permite una evaporación controlada, favoreciendo la estandarización en procesos de higiene y aportando a la continuidad operativa mediante un insumo estratégico que optimiza tiempos de aplicación y mantiene condiciones adecuadas de uso en entornos de trabajo.', 12230.00, 20, 22, true, false, 'https://www.abastece.co/abastece/images/76078.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Aposito Transparente Absorbente + Pad 6 X 7 Cm Paq.x 3u.', 'aposito-transparente-absorbente-pad-6-x-7-cm-paqx-3u-74902', 'Aposito Transparente Absorbente + Pad 6 X 7 Cm Paq.x 3u.', 25402.00, 20, 19, true, false, 'https://www.abastece.co/abastece/images/74902.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Arnes Reflectivo Para Camilla Plastica', 'arnes-reflectivo-para-camilla-plastica-75158', 'Arnés Reflectivo para Camilla Plástica x Unidad Seguridad operativa que optimiza el control en traslado Arnés reflectivo diseñado para camilla plástica, fabricado en material de alta resistencia con bandas reflectivas de alta visibilidad que mejoran la identificación en condiciones de baja iluminación. Su sistema de ajuste seguro facilita la sujeción del paciente o carga, favoreciendo la estandarización en procesos de atención y aportando a la continuidad operativa mediante un insumo estratégico que optimiza tiempos de inmovilización y refuerza la seguridad en el entorno.', 25284.00, 20, 45, true, false, 'https://www.abastece.co/abastece/images/75158.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Bajalenguas de Madera Paq.x20u.', 'bajalenguas-de-madera-paqx20u-5549', 'Bajalenguas de Madera Paquete por 20 Unidades Herramienta Esencial para Uso Médico y Educativo Los Bajalenguas de Madera, presentados en un paquete de 20 unidades, son una herramienta básica y esencial en entornos médicos y educativos. Fabricados con madera de alta calidad, estos bajalenguas son suaves, resistentes y perfectos para exploraciones orales o procedimientos médicos. Su diseño liso y cómodo permite un uso fácil y seguro durante exámenes físicos o como herramienta para manualidades en clases de arte. Son ideales para profesionales de la salud, escuelas, clínicas y hogares. El paquete de 20 unidades asegura que siempre tendrás a mano este artículo imprescindible.', 1115.00, 20, 30, true, false, 'https://www.abastece.co/abastece/images/5549.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Base Para Extintor De Piso X 10 Libras', 'base-para-extintor-de-piso-x-10-libras-71657', 'Base para Extintor de Piso x 10 Libras x Unidad Soporte estable que optimiza la organización de seguridad Base de piso para extintor de 10 libras, fabricada en material resistente de alta durabilidad que garantiza estabilidad y correcta ubicación del equipo. Su diseño funcional permite una instalación rápida y segura, favoreciendo la estandarización en puntos de seguridad y aportando a la continuidad operativa mediante un insumo estratégico que optimiza tiempos de instalación y mejora la accesibilidad en situaciones de emergencia.', 11760.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/71657.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Base Para Extintor De Piso X 20 Libras', 'base-para-extintor-de-piso-x-20-libras-75104', 'Base para Extintor de Piso x 20 Libras x Unidad Soporte reforzado que optimiza la seguridad y organización Base de piso diseñada para extintor de 20 libras, fabricada en material resistente de alta durabilidad que garantiza estabilidad y soporte adecuado para equipos de mayor peso. Su estructura funcional permite una instalación rápida y segura, favoreciendo la estandarización en puntos de seguridad y aportando a la continuidad operativa mediante un insumo estratégico que optimiza tiempos de ubicación y mejora la accesibilidad en situaciones de emergencia.', 15288.00, 20, 39, true, false, 'https://www.abastece.co/abastece/images/75104.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Bata De Laboratorio Desechable Con Velcro Blanca x10', 'bata-de-laboratorio-desechable-con-velcro-blanca-x10-75321', 'Bata de Laboratorio Desechable Blanca con Velcro Paq x 10 Unidades Protección ligera que optimiza la bioseguridad operativa Pack de 10 batas desechables de laboratorio en color blanco, fabricadas en material no tejido liviano y resistente con sistema de cierre en velcro para ajuste práctico y rápido. Su diseño de uso único facilita la rotación higiénica, favoreciendo la estandarización en procesos de protección y aportando a la continuidad operativa mediante un insumo estratégico que optimiza tiempos de dotación y mantiene condiciones adecuadas de seguridad.', 41074.00, 20, 46, true, false, 'https://www.abastece.co/abastece/images/75321.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Bata Desechable Con Cremallera Talla L Blanca', 'bata-desechable-con-cremallera-talla-l-blanca-75272', 'Bata Desechable Blanca con Cremallera Talla L x Unidad Protección funcional que optimiza la continuidad operativa Bata desechable en color blanco talla L, fabricada en material no tejido liviano y resistente con sistema de cierre en cremallera frontal que facilita su uso rápido. Su diseño de un solo uso favorece la gestión higiénica y la rotación eficiente de dotación, contribuyendo a la estandarización en procesos de protección y a la continuidad operativa mediante un insumo estratégico que optimiza tiempos de alistamiento y mantiene condiciones adecuadas de bioseguridad.', 7063.00, 20, 50, true, false, 'https://www.abastece.co/abastece/images/75272.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Bata En Tela Dacron Manga Larga Talla M Blanca', 'bata-en-tela-dacron-manga-larga-talla-m-blanca-74589', 'Bata en Tela Dacrón Blanca Manga Larga Talla M x Unidad Presentación profesional que optimiza la funcionalidad en entornos técnicos Bata en tela dacrón de alta resistencia en color blanco, con manga larga y ajuste ergonómico talla M, diseñada para uso prolongado en entornos de laboratorio o trabajo técnico. Su material ofrece durabilidad, fácil mantenimiento y buena presentación, favoreciendo la estandarización en dotación institucional y aportando a la continuidad operativa mediante un insumo estratégico que optimiza tiempos de alistamiento y refuerza la imagen profesional del entorno.', 26387.00, 20, 54, true, false, 'https://www.abastece.co/abastece/images/74589.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Bata Laboratorio Desechable Azul x10', 'bata-laboratorio-desechable-azul-x10-3372', 'Bata de Laboratorio Desechable Azul Paquete x 10 u: Protección y Comodidad Ideal para Entornos de Trabajo en Laboratorios y Clínicas Te presentamos la Bata de Laboratorio Desechable Azul, disponible en un práctico paquete de 10 unidades, diseñada para brindar protección y comodidad en entornos de trabajo. Fabricadas con materiales ligeros y resistentes, estas batas son perfectas para mantener la higiene y seguridad en laboratorios, clínicas y otros espacios donde se requiere cuidado especial. Su diseño desechable facilita la limpieza y evita la contaminación cruzada. ¡Asegura la protección de tu vestimenta y la de tus pacientes con nuestras batas desechables!', 26342.00, 20, 40, true, false, 'https://www.abastece.co/abastece/images/3372.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Bata Laboratorio Desechable Blanca x10', 'bata-laboratorio-desechable-blanca-x10-3688', 'Bata Laboratorio Desechable Blanca Paquete x 10 u Protección y comodidad para un entorno de trabajo seguro La Bata Laboratorio Desechable Blanca es perfecta para mantener la higiene y seguridad en entornos como laboratorios, hospitales y áreas de trabajo en donde se requiere protección. Hecha de material ligero y resistente, esta bata ofrece comodidad durante su uso prolongado y está diseñada para ser desechable, lo que garantiza una solución higiénica y económica. El paquete incluye 10 unidades, asegurando suficiente cantidad para equipos de trabajo o uso individual en tareas que exijan limpieza y protección.', 26342.00, 20, 45, true, false, 'https://www.abastece.co/abastece/images/3688.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Biombo 3 Cuerpos En Tela', 'biombo-3-cuerpos-en-tela-74528', 'Biombo 3 Cuerpos en Tela x Unidad División funcional que optimiza la privacidad y organización del espacio Biombo de 3 cuerpos elaborado en estructura resistente con recubrimiento en tela, diseñado para facilitar la separación de ambientes de forma práctica y estable. Su formato plegable permite fácil transporte y almacenamiento, favoreciendo la estandarización en la organización de espacios y aportando a la continuidad operativa mediante un insumo estratégico que optimiza tiempos de instalación y mejora la funcionalidad del entorno.', 575064.00, 20, 43, true, false, 'https://www.abastece.co/abastece/images/74528.jpg'),
('c1111111-1111-1111-1111-111111111111', 'BOLSA PARA HIELO- Golpes, Contusiones ,inflamaciones,dolores', 'bolsa-para-hielo-golpes-contusiones-inflamacionesdolores-9222', 'Bolsa para Hielo x Unidad Aplicación terapéutica que optimiza el alivio de molestias Bolsa reutilizable para aplicación de hielo, diseñada para apoyo en casos de golpes, contusiones, inflamaciones y dolores. Fabricada en material resistente y flexible con cierre seguro que evita fugas y facilita su uso directo sobre la zona afectada. Su diseño práctico permite una aplicación rápida y controlada, favoreciendo la estandarización en primeros auxilios y aportando a la continuidad operativa mediante un insumo funcional que optimiza tiempos de respuesta y mejora el manejo del malestar.', 19764.00, 20, 31, true, false, 'https://www.abastece.co/abastece/images/9222.jpg'),
('c1111111-1111-1111-1111-111111111111', 'Boquillas Desechables Para Alcoholímetro Paquete X400u.', 'boquillas-desechables-para-alcoholimetro-paquete-x400u-75393', 'Boquillas Desechables para Alcoholímetro Paquete x 400 Unidades Higiene y control que optimizan la seguridad en pruebas de alcoholemia Boquillas desechables para alcoholímetro, presentadas en paquete por 400 unidades, fabricadas en material plástico sanitario de alta calidad, diseñadas para garantizar una medición segura, higiénica y confiable en pruebas de alcoholemia en entornos institucionales, de tránsito, seguridad o control laboral, su diseño de uso único evita la contaminación cruzada entre usuarios asegurando condiciones sanitarias adecuadas en cada prueba, favoreciendo la estandarización en insumos de control y aportando a la continuidad operativa mediante un insumo estratégico que optimiza la bioseguridad, la precisión de los resultados y la eficiencia en los procesos de verificación.', 209328.00, 20, 29, true, false, 'https://www.abastece.co/abastece/images/75393.jpg'),
